#!/usr/bin/env node
/**
 * Port the skin tokens of codegen-x/ui8kit into packages/theme/src/skin-tokens.ts.
 *
 *   node scripts/port-skins.mjs <codegen-x/ui8kit>/packages/shared/app/src/styles/skins
 *
 * Reads every skin CSS file (generated by compose-gen from tweakcn presets, Apache-2.0, see packages/theme/NOTICE-skins.md),
 * keeps the colour tokens of the light rule and of the dark rule, the skin's --radius and its --shadow-sm / --shadow-md.
 * Fonts, tracking and the other shadow steps are not ported (fonts are not part of this constructor).
 * The values are copied verbatim, so a skin here paints exactly what it paints in codegen-x.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const dir = process.argv[2];
if (!dir) {
  console.error("usage: node scripts/port-skins.mjs <skins dir>");
  process.exit(2);
}
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const out = path.join(root, "packages/theme/src/skin-tokens.ts");
const SKINS = ["default", "sky", "modern-minimal", "violet-bloom", "t3-chat", "bubblegum", "doom-64", "amber-minimal", "supabase",
  "kodama-grove", "perpetuity", "cosmic-night", "claude", "mocha-mousse", "neo-brutalism", "notebook", "rose"];
const KEEP = (name, value) => value.startsWith("hsl(") || name === "radius" || name === "shadow-sm" || name === "shadow-md";

function rules(css) {
  const clean = css.replace(/\/\*[\s\S]*?\*\//g, "");
  const found = [];
  const re = /([^{}]+)\{([^{}]*)\}/g;
  let m;
  while ((m = re.exec(clean))) found.push({ selector: m[1].trim(), body: m[2] });
  return found;
}
function vars(body) {
  const o = {};
  for (const line of body.split(";")) {
    const m = /^\s*--([a-z0-9-]+)\s*:\s*([\s\S]+?)\s*$/.exec(line);
    if (m && KEEP(m[1], m[2])) o[m[1]] = m[2].replace(/\s+/g, " ");
  }
  return o;
}

const base = vars(rules(fs.readFileSync(path.join(dir, "base.css"), "utf8"))[0].body);
const table = {};
for (const id of SKINS) {
  const all = rules(fs.readFileSync(path.join(dir, `${id}.css`), "utf8")).filter((r) => r.selector.includes("data-skin"));
  const light = all.find((r) => !r.selector.includes(".dark"));
  const dark = all.find((r) => r.selector.includes(".dark"));
  if (!light || !dark) throw new Error(`${id}: light or dark rule missing`);
  const l = vars(light.body);
  const d = vars(dark.body);
  // CSS cascade: the dark rule overrides the light one, so what the dark rule does not set (radius, shadows) stays the light value.
  const extra = id === "default" ? { "shadow-sm": base["shadow-sm"], "shadow-md": base["shadow-md"] } : {};
  const lightAll = { ...extra, ...l };
  table[id] = { light: lightAll, dark: { ...lightAll, ...d } };
}

const body = JSON.stringify(table, null, 2).replace(/"([a-z][a-z0-9-]*)":/g, (s, k) => (/^[a-z][a-z0-9]*$/.test(k) ? `${k}:` : s));
fs.writeFileSync(
  out,
  `// Code generated by scripts/port-skins.mjs from codegen-x/ui8kit packages/shared/app/src/styles/skins. DO NOT EDIT.
// tweakcn presets (Apache-2.0) and ui8kit skins: see packages/theme/NOTICE-skins.md. Values verbatim: colour tokens of the light
// and dark rule (keys without "--"), the skin's radius and its shadow-sm / shadow-md. "default" is the shadcn neutral theme.
export const SKIN_TOKENS: Record<string, { light: Record<string, string>; dark: Record<string, string> }> = ${body};
`,
);
console.log(`wrote ${path.relative(root, out)} (${SKINS.length} skins)`);
